<script setup lang="ts">import { onMounted,ref } from 'vue';import { api } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const items=ref<any[]>([]),error=ref(''),loading=ref(true);async function load(){loading.value=true;try{items.value=await api('/approvals/inbox')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}onMounted(load)</script>
<template><section class="panel"><div class="panel-head"><div><h2>Approval inbox</h2><p>Maker-checker, expiry, partial scope, simulator identity, and plan-hash binding.</p></div><button @click="load">Refresh</button></div><AsyncState :loading="loading" :error="error" :empty="!items.length"><article v-for="item in items" :key="item.approval_id" class="list-row"><div><strong>{{item.approval_id}}</strong><span>{{item.request.run_id}} · risk {{item.request.risk}}</span></div><span class="pill">{{item.state}}</span></article></AsyncState></section></template>
